def check_subset_list(subset, superset):
    def normalize(lst):
        result = []
        for item in lst:
            if isinstance(item, list):
                result.append(normalize(item))
            else:
                result.append(item)
        return result

    def is_subset(sub, sup):
        if isinstance(sub, list) and isinstance(sup, list):
            if len(sub) > len(sup):
                return False
            for s in sub:
                found = False
                for sp in sup:
                    if is_subset(s, sp):
                        found = True
                        break
                if not found:
                    return False
            return True
        return sub == sup

    return is_subset(normalize(subset), normalize(superset))
