        max_r = max(r for r, c in rows)
        min_c = min(c for r, c in rows)
        max_c = max(c for r, c in rows)

        # Extract the minimal bounding box
        h = max_r - min_r + 1
        w = max_c - min_c + 1

        # Create a minimal representation
        min_grid = []
        for r in range(h):
            row_str = ""
            for c in range(w):
                if poly[min_r + r][min_c + c] == '#':
                    row_str += '#'
                else:
                    row_str += '.'
            min_grid.append(row_str)

        # Apply rotation
